{
  "situation": "We know that fraud model v2 went live at 08:00 for SIM-replacement requests and refused SIM replacements increased about tenfold, with the dashboard labelling it a 'fraud wave'. We do not know whether the refusals are genuine fraud or false positives, nor the model's threshold or customer impact.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "A fraud model change has produced a tenfold increase in refused SIM replacements, which may indicate an incident affecting personal data processing.",
        "rule": "UAE PDPL requires controllers to protect and secure data processing and the devices used in processing.",
        "inference": "Preserving logs is necessary to secure evidence and support investigation of the anomaly."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "6. Protect and secure data processing, the electronic media and devices used in processing and the Personal Data they contain."
        }
      ]
    },
    {
      "type": "action",
      "verb": "rollback_model",
      "params": {"version": "v1"},
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 went live for SIM-replacement requests at 08:00 and the fraud dashboard shows refused SIM replacements up about tenfold.",
        "rule": "Global benchmark says the vast majority of SIM change and port-out requests are legitimate and processing should avoid undue burdens that hinder access to wireless services.",
        "inference": "The tenfold increase immediately after the change suggests the model may be overblocking legitimate customers, so rolling back to v1 is the appropriate containment action."
      },
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "The record reflects that the vast majority of SIM change and port-out requests are legitimate. It also shows that the efficient and effective processing of SIM changes and port-out requests promotes customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "The retrieved UAE text does not require OpCo to notify customers when automated fraud detection blocks a SIM-replacement request; notification is required only for planned service interruptions.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "The fraud model v2 went live and refused SIM replacements increased tenfold, potentially affecting legitimate customers.",
        "rule": "UAE-LIC 12.9.1 imposes customer notification only for planned interruptions, not for automated fraud refusals.",
        "inference": "There is a regulatory gap regarding customer notification for fraud-model-driven service restrictions."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "We also adopt rules that will enable customers to act to prevent and address fraudulent SIM changes and number ports, including requiring that wireless providers notify customers regarding SIM change and port-out requests, offer customers the option to lock their accounts to block processing of SIM changes and number ports, and give advanced notice of available account protection mechanisms."
        }
      ]
    }
  ]
}

{
  "situation": "OpCo's fraud model v2 went live at 08:00 and caused a tenfold increase in refused SIM replacements; we rolled back to v1, leaving 18 customers locked out of banking. We do not yet know whether a data protection impact assessment was completed before v2 deployment or whether the refusals constitute a personal data breach.",
  "claims": [
    {
      "type": "action",
      "verb": "alt_auth_route",
      "params": {
        "cohort": "bank_flagged"
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01"
      ],
      "rationale": {
        "observation": "After rollback to v1, twin metrics show legit_pass_rate 0.9909 but locked_out_banking 18.",
        "rule": "UAE PDPL Article 18 gives data subjects the right to object to automated decisions that adversely affect them.",
        "inference": "Offering a non-SMS confirmation route to bank-flagged customers can mitigate adverse automated refusal decisions and respect their rights."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0060",
          "quote": "The Data Subject shall have the right to object to any decisions resulting from automated processing, including profiling, particularly those decisions which have legal impact on or adversely affect the Data Subject."
        }
      ]
    },
    {
      "type": "action",
      "verb": "enable_review_queue",
      "params": {},
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "Fraud model v2 caused refused SIM replacements to rise about tenfold, indicating possible false positives.",
        "rule": "UAE PDPL Article 18 requires safeguards against automated decisions with adverse effects.",
        "inference": "Sending borderline automated refusals to human review provides a safeguard before decisions adversely affect customers."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0060",
          "quote": "The Data Subject shall have the right to object to any decisions resulting from automated processing, including profiling, particularly those decisions which have legal impact on or adversely affect the Data Subject."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "Before deploying fraud model v2, OpCo was required to evaluate the impact of the proposed processing on personal data protection because the model uses modern technologies that pose high risk to privacy.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and processed SIM-replacement requests, causing a tenfold increase in refusals.",
        "rule": "UAE PDPL Article 21 requires controllers to evaluate the impact of proposed processing before carrying it out when using modern technologies that would pose high risk.",
        "inference": "This deployment falls under the DPIA obligation; we must verify that the evaluation was completed before go-live."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "insufficient_evidence",
      "statement": "The inbox and knowledge excerpts do not show whether a data protection impact assessment was completed before fraud model v2 went live.",
      "inject_refs": [
        "S3-I1"
      ],
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "share",
      "to": [
        "REG",
        "DPA"
      ],
      "inject_refs": [
        "S3-I1",
        "S3-FB01"
      ],
      "statement": "OpCo's fraud model v2 went live at 08:00, refused SIM replacements increased about tenfold, and after rollback to v1, 18 customers remain locked out of banking."
    }
  ]
}

{
  "situation": "We know fraud model v2 went live at 08:00, refused SIM replacements increased tenfold, and rollback to v1 plus alt_auth_route and review queue have been completed. We do not know whether a data protection impact assessment was completed before v2 went live or whether any personal data was compromised.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02", "S3-FB03"],
      "rationale": {
        "observation": "Fraud model v2 caused a tenfold increase in refused SIM replacements, followed by rollback to v1, alt_auth_route for bank-flagged customers, and enable_review_queue.",
        "rule": "UAE PDPL defines Personal Data Security as technical and organizational measures that maintain integrity and availability of Personal Data.",
        "inference": "Preserving logs and evidence maintains the integrity and availability of records needed for incident review and regulatory scrutiny."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0002",
          "quote": "Personal Data Security:A set of technical and organizational measures, procedures and processes specified in accordance with provisions of this Decree by Law which maintain the protection of privacy, confidentiality, integrity and availability of Personal Data"
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo, as Controller, must evaluate the data protection impact of the fraud model v2 automated processing before any continued use because the model uses automated means and may pose a high risk to the privacy and confidentiality of data subjects.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and refused SIM replacements increased about tenfold, indicating automated processing with potentially high privacy risk.",
        "rule": "UAE PDPL Article 21 requires the Controller to evaluate the impact of processing before carrying it out when using modern technologies that would pose a high risk to privacy and confidentiality.",
        "inference": "The fraud model v2 is high-risk automated processing, so a data protection impact assessment is required before continuing to use it."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_owner",
      "statement": "The incident exposes that OpCo has no identifiable owner or operational checkpoint to ensure a data protection impact assessment is completed and reviewed before a high-risk fraud model version is deployed, even though UAE law requires impact assessment before processing.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and immediately caused a tenfold increase in refused SIM replacements, with no mention of a DPIA checkpoint in the release process.",
        "rule": "UAE PDPL Article 21 requires the Controller to evaluate the impact before carrying out high-risk processing.",
        "inference": "Without a named owner or checkpoint in the model release process, the DPIA obligation can be missed, as suggested by the sudden v2 go-live and its immediate impact."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0203",
          "quote": "Where necessary, the controller shall carry out a review to assess if processing is performed in accordance with the data protection impact assessment at least when there is a change of the risk represented by processing operations."
        }
      ]
    },
    {
      "type": "share",
      "to": ["REG", "DPA"],
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02", "S3-FB03"],
      "statement": "Forwarding fraud model v2 go-live, dashboard anomaly, rollback to v1, alt_auth_route for bank-flagged, and review queue metrics to the regulator and data protection authority for situational awareness."
    }
  ]
}

{
  "situation": "OpCo's fraud model v2 went live for SIM replacement requests at 08:00 and its dashboard shows refused SIM replacements up about tenfold, labelled a 'fraud wave'; feedback confirms rollback to v1, alternative authentication for bank-flagged customers, and a review queue, with metrics now normalised. I do not yet know how many legitimate replacement requests were wrongly refused, the root cause of the false positives, or whether any customers suffered financial or service harm.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "SIM replacement fraud wave and elevated refusals at OpCo"
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02",
        "S3-FB03"
      ],
      "rationale": {
        "observation": "OpCo reports fraud model v2 went live for SIM replacement requests at 08:00 and the fraud dashboard shows refused SIM replacements up about tenfold, labelled a 'fraud wave'; feedback then shows rollback to v1, alternative authentication for bank-flagged customers, and a review queue.",
        "rule": "TDRA has statutory power under the Telecommunications Law to regulate the conditions, level and scope of services provided by licensees to subscribers, including standards and quality of services.",
        "inference": "This abnormal refusal spike and subsequent emergency remediation is a regulatory incident that TDRA should formally record and track."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Impact of fraud model v2 on legitimate SIM replacement requests, refusal rates, and customer harm"
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02",
        "S3-FB03"
      ],
      "rationale": {
        "observation": "Feedback metrics show a temporary locked-out banking figure of 18 and a legit_pass_rate of 0.9909 before alternative authentication and review queue changes, but no explanation of the root cause or customer impact of the tenfold refusal spike.",
        "rule": "TDRA has power to regulate service quality and handling of subscriber issues under the Consumer Protection Regulations.",
        "inference": "TDRA should require OpCo to report on the cause, impact, and remediation of the fraud model v2 incident."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_audit",
      "params": {
        "of": "NOC",
        "topic": "Testing, change approval and deployment records for fraud model v2 SIM replacement screening"
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02",
        "S3-FB03"
      ],
      "rationale": {
        "observation": "OpCo deployed fraud model v2 at 08:00, saw refusals rise tenfold, then rolled back to v1 and enabled alternative authentication and a review queue the same day.",
        "rule": "TDRA has statutory power to regulate services and may require the licensee's testing and change records.",
        "inference": "TDRA should audit whether proper testing, change approval and deployment controls were followed for this high-impact SIM replacement model change."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Do not redeploy fraud model v2 for SIM replacement screening until TDRA has reviewed the audit and report; maintain the current v1 model, alternative authentication route and review queue."
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02",
        "S3-FB03"
      ],
      "rationale": {
        "observation": "OpCo has already rolled back to v1 and enabled alternative authentication and a review queue, but v2 was launched without apparent TDRA approval and caused an abnormal fraud-wave label and refusal spike.",
        "rule": "TDRA may direct a licensee on resilience or continuity and on service standards under the Consumer Protection Regulations.",
        "inference": "A direction is needed to preserve the safer operating state and prevent premature redeployment of the problematic model."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "The UAE regulatory excerpts shown do not contain an explicit rule requiring mobile licensees to use secure SIM replacement authentication, notify customers of SIM swap attempts, or investigate and remediate SIM swap fraud; global regulators have codified these duties and implementation deadlines.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "The only UAE telecom consumer regulation excerpt retrieved addresses Credit Limits information, not SIM replacement security, while a 2022 UAE court case found a telecom provider issued a replacement SIM without following identification protocol.",
        "rule": "TDRA's Consumer Protection Regulations power is broad, but no specific SIM-swap fraud rule or deadline appears in the retrieved UAE telecom texts.",
        "inference": "This incident exposes a regulatory gap: there is no explicit SIM-swap fraud protection rule comparable to the FCC's SIM swap and port-out fraud rules."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0160",
          "quote": "Licensees had certain obligations regarding the provision of information to subscribers. It is the Licensee’s responsibility to have complied with those requirements and thus, all ‘existing subscribers’ shall, at the effective date of these regulations, have been provided with the proper information regarding Credit Limits."
        },
        {
          "chunk_id": "UAE-PRESS-SIMSWAP-COURT-2022#0000",
          "quote": "the telecoms service provider issued a new SIM card to fraudsters in March 2019 under the client's registered mobile number without following identification protocol."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "requiring that wireless providers notify customers regarding SIM change and port-out requests, offer customers the option to lock their accounts to block processing of SIM changes and number ports, and give advanced notice of available account protection mechanisms."
        },
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "We are wary of setting rigid requirements that would impose significant burdens on customers without substantially protecting against SIM swap and port-out fraud."
        },
        {
          "chunk_id": "US-FCC-DA-24-649#0008",
          "quote": "providing six months to achieve compliance with rules that are not subject to OMB review"
        },
        {
          "chunk_id": "US-FCC-23-95#0040",
          "quote": "proactively and regularly review and monitor their policies and procedures to ensure that they continue to be effective at addressing evolving fraud techniques against customer accounts and services--including SIM swap and port-out fraud--and to conduct analyses of fraud incidents to determine how the fraud occurred and implement measures to prevent such tactics from being successful again in the future."
        }
      ]
    },
    {
      "type": "share",
      "to": [
        "DPA",
        "FIN"
      ],
      "inject_refs": [
        "S3-I1"
      ],
      "statement": "Forwarding OpCo's fraud-wave alert to the Data Protection Authority and financial sector bodies because SIM replacement fraud may involve personal data and banking authentication."
    }
  ]
}

{
  "situation": "I know NOC rolled out fraud model v2 for SIM-replacement requests at 08:00, saw refused SIM replacements rise about tenfold, then rolled back to v1 and applied alt_auth_route and review queue changes. I do not know whether a personal data breach occurred, how many data subjects were affected, or whether any cross-border transfer was involved.",
  "claims": [
    {
      "type": "action",
      "verb": "request_human_review_record",
      "params": {
        "from": "NOC"
      },
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "NOC reports that fraud model v2 went live for SIM-replacement requests and refused SIM replacements rose about tenfold.",
        "rule": "UAE-PDPL#0047 gives data subjects the right to obtain 'Decisions made based on automated processing, including profiling.'",
        "inference": "To verify this right and assess the automated fraud model decisions, the Bureau should require records of human review of those automated decisions."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "Decisions made based on automated processing, including profiling."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "The incident exposes that the UAE PDPL excerpts contain no explicit deadline for a controller to notify the Bureau of a personal data breach; the only quoted breach-related duty is a data subject right to information.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "NOC's 08:00 message reports a sharp refusal spike but no controller-to-Bureau breach notification.",
        "rule": "UAE-PDPL#0047 mentions actions in the event of a breach only as information to the data subject; no deadline for notifying the Bureau is quoted.",
        "inference": "There is a no_deadline gap for controller breach notification to the Bureau."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "Actions to be taken in the event of a breach or misuse of his/ her Personal Data, especially if the breach or misuse has a direct and serious threat to the privacy and confidentiality of his/her Personal Data."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0040",
          "quote": "It should be ascertained whether all appropriate technological protection and organisational measures have been implemented to establish immediately whether a personal data breach has taken place and to inform promptly the supervisory authority and the data subject."
        }
      ]
    },
    {
      "type": "share",
      "to": [
        "FIN",
        "REG"
      ],
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02",
        "S3-FB03"
      ],
      "statement": "NOC's fraud-model change caused a tenfold rise in SIM-replacement refusals, then rollback and alt_auth_route cleared locked-out banking; sharing with financial and telecom regulators for sector oversight."
    }
  ]
}

{
  "situation": "We know OpCo's fraud model v2 caused a tenfold rise in refused SIM replacements and was rolled back with additional mitigations; banks still report customers abroad locked out of online banking because OpCo refused their SIM replacement requests. We do not know OpCo's current SIM replacement authentication process for customers abroad or why the refusals persist after the rollback.",
  "claims": [
    {
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "content": "Licensed banks must ensure customers abroad can authenticate without SMS OTP, including in-app authentication, and must provide support to customers locked out after SIM replacement refusals."
      },
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "Banks report customers abroad cannot receive one-time passcodes and are locked out of online banking because OpCo refused their SIM replacement requests.",
        "rule": "The Central Bank has told banks that OTPs should not be sent through weak modes like SMS and email, and has directed them to use more secure in-app authentication.",
        "inference": "The Central Bank can instruct banks to activate alternative authentication paths so that customers abroad are not left locked out."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised"
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "REG",
        "content": "OpCo SIM replacement refusals are causing bank customers abroad to be locked out of online banking; please investigate OpCo's authentication process for overseas SIM replacement requests."
      },
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "OpCo's fraud model v2 went live and SIM replacement refusals rose about tenfold, and banks report customers abroad locked out.",
        "rule": "Telecom providers have been held responsible when SIM card issuance fails to follow identification protocol, and the Central Bank has flagged SMS OTP issues for customers abroad.",
        "inference": "REG should be notified to address OpCo's SIM replacement refusals that are blocking legitimate bank customers."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-SIMSWAP-COURT-2022#0000",
          "quote": "the telecoms service provider issued a new SIM card to fraudsters in March 2019 under the client's registered mobile number without following identification protocol."
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "Customers travelling outside the UAE have complained of not receiving the SMS containing the OTP or receiving it after the valid time period."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No UAE rule requires mobile operators to maintain a review or alternative authentication path for legitimate SIM replacement requests flagged as fraud, leaving customers abroad locked out when automated fraud controls over-refuse.",
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "Fraud model v2 caused a tenfold increase in refused SIM replacements, and banks report customers abroad locked out after OpCo refused their SIM replacement requests.",
        "rule": "UAE law holds telecom providers liable after a fraudulent SIM swap, but the excerpts do not show a preventive rule requiring an accessible process for legitimate overseas SIM replacements.",
        "inference": "This exposes a policy gap: fraud controls can block legitimate customers without a mandated review or alternative authentication route."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-SIMSWAP-COURT-2022#0000",
          "quote": "The Dubai Court of Cassation ordered a UAE-based bank and telecommunications company to return Dh1.5 million that a client had lost in unauthorised transactions."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0118",
          "quote": "requires that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports, and to review and update these authentication methods as needed, but at least annually."
        }
      ]
    }
  ]
}

{
  "situation": "FIN reports that OpCo SIM replacement refusals are locking overseas bank customers out of online banking and asks us to investigate the authentication process. I know NOC already rolled back the fraud model and reports metrics showing zero locked-out banking and full legit pass rate, but I do not yet have OpCo's overseas SIM replacement authentication process details.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
